The quartiles of a ranked set of data values are three points that divide the data into exactly four equal parts, each part comprising quarter data. Q1 is defined as the middle number between the smallest number and the median of the data set.Q2 is the median of the data.Q3 is the middle value between the median and the highest value of the data set.The interquartile range IQR tells us the range where the bulk of the values lie. The interquartile range is calculated by subtracting the first quartilefrom the third quartile. IQR = Q3 - Q1Uses 1. Unlike range, IQR tells where the majority of data lies and is thus preferred over range. 2. IQR can be used to identify outliers in a data set. 3. Gives the central tendency of the data. Examples: Input : 1, 19, 7, 6, 5, 9, 12, 27, 18, 2, 15Output : 13The data set after being sorted is 1, 2, 5, 6, 7, 9, 12, 15, 18, 19, 27As mentioned above Q2 is the median of the data. Hence Q2 = 9Q1 is the median of lower half, taking Q2 as pivot.So Q1 = 5Q3 is the median of upper half talking Q2 as pivot. So Q3 = 18Therefore IQR for given data=Q3-Q1=18-5=13 Input : 1, 3, 4, 5, 5, 6, 7, 11Output : 3Below is the implementation of the above approach:
            C++

    #include <iostream>
#include <algorithm>

using namespace std;

// Function to give 
// index of the median
int median(int l, int r){
    int n = r - l + 1;
    n = (n + 1) / 2 - 1;
    return n + l;
}

// Function to 
// calculate IQR
int IQR(int a[], int n){
    sort(a, a + n);

    // Index of median 
    // of entire data
    int mid_index = median(0, n - 1);

    // Median of first half
    int Q1;
    if (n % 2 == 0)
        Q1 = a[median(0, mid_index)];
    else
        Q1 = a[median(0, mid_index - 1)];

    // Median of second half
    int Q3;
    if (n % 2 == 0)
        Q3 = a[median(mid_index + 1, n - 1)];
    else
        Q3 = a[median(mid_index + 1, n)];

    // IQR calculation
    return (Q3 - Q1);
}

// Driver Code
int main() {
    int a[] = {1, 19, 7, 6, 5, 9, 12, 27, 18, 2, 15};
    int n = sizeof(a) / sizeof(a[0]);
    cout << IQR(a, n) << endl;
    return 0;
}


