// Function to give 
// index of the median
function median(l, r) {
    let n = r - l + 1;
    n = Math.floor((n + 1) / 2) - 1;
    return n + l;
}

// Function to 
// calculate IQR
function IQR(a, n) {
    a.sort((x, y) => x - y);

    // Index of median 
    // of entire data
    let mid_index = median(0, n - 1);

    // Median of first half
    let Q1 = a[median(0, mid_index)];

    // Median of second half
    let Q3;
    if (n % 2 === 0)
        Q3 = a[median(mid_index + 1, n - 1)];
    else
        Q3 = a[median(mid_index + 1, n)];

    // IQR calculation
    return Q3 - Q1;
}

